```c
#include <stdio.h>

#define MAXN 100005

int dp[MAXN];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = 1000000000;
        int temp = i;
        while (temp > 0) {
            int d = temp % 10;
            temp /= 10;
            if (d > 0) {
                if (dp[i - d] + 1 < dp[i]) {
                    dp[i] = dp[i - d] + 1;
                }
            }
        }
    }

    printf("%d\n", dp[n]);
    return 0;
}
```

